/**
 * `NormalizedFileReader` → an editable variant-specific file-reader factory,
 * configured `{ ref, def }` builder call exported as default — same
 * convention as the other configured-builder printers (`print-skill-v2.ts`,
 * `print-agent.ts`). File readers carry no catalog-token references of their
 * own (`parent` is a plain refName string), so this needs no `ImportTracker`.
 */
import { sdkPackageSpecifier } from "../../../internal/sdk-package.js";
export function printFileReader(model, opts) {
    const { payload } = model;
    const factory = `${payload.type}FileReader`;
    const lines = [];
    lines.push(`/**`);
    lines.push(` * Auto-generated by EDK (pull). Hand-edit freely; the generator is a`);
    lines.push(` * one-shot starting point, not a live-binding view.`);
    lines.push(` */`);
    lines.push("");
    lines.push(`import { ${factory}${payload.type === "json" || payload.type === "xml" ? ", fileReaderStructure" : ""} } from "${sdkPackageSpecifier("fileReaders")}";`);
    lines.push(`import catalog from "@catalog";`);
    lines.push("");
    lines.push(`const fileReader = ${factory}({`);
    lines.push(`  name: ${quote(payload.name)},`);
    lines.push(`  owner: catalog.${opts.parent},`);
    const body = printBody(payload);
    if (body.length > 0)
        lines.push(body);
    lines.push(`});`);
    lines.push("");
    lines.push(`export default fileReader;`);
    return lines.join("\n") + "\n";
}
function printBody(payload) {
    switch (payload.type) {
        case "excel":
            return [
                `  firstRowIsHeader: ${payload.firstRowIsHeader},`,
                `  fields: ${printExcelFields(payload.fields)},`,
                // documentContent/documentName/fileType are never recoverable from
                // the platform (its own schema docs say so - Read() never returns
                // any of the three on an already-imported resource), so pull never
                // sets them: only needed to CREATE a genuinely new Excel reader, e.g.
                //   documentContent: filebase64("path/to/sample.xlsx"),
                //   documentName: "sample.xlsx",
                //   fileType: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
                ...(payload.documentContent !== undefined ? [`  documentContent: ${quote(payload.documentContent)},`] : []),
                ...(payload.documentName !== undefined ? [`  documentName: ${quote(payload.documentName)},`] : []),
                ...(payload.fileType !== undefined ? [`  fileType: ${quote(payload.fileType)},`] : []),
            ].join("\n");
        case "json":
        case "xml":
            return `  structure: ${printStructure(payload.structure, 1)},`;
        case "text":
            return "";
        case "ai":
            return [
                `  instructions: ${quote(payload.instructions)},`,
                `  fields: ${printAiFields(payload.fields)},`,
            ].join("\n");
    }
}
function printAiFields(fields) {
    if (fields.length === 0)
        return "[]";
    const items = fields.map((f) => {
        const parts = [`name: ${quote(f.name)}`, `description: ${quote(f.description)}`, `type: ${quote(f.type)}`];
        if (f.required !== undefined)
            parts.push(`required: ${f.required}`);
        return `{ ${parts.join(", ")} }`;
    });
    return `[\n    ${items.join(",\n    ")},\n  ]`;
}
function printExcelFields(fields) {
    if (fields.length === 0)
        return "[]";
    const items = fields.map((f) => {
        const parts = [`name: ${quote(f.name)}`, `type: ${quote(f.type)}`, `location: { sheet: ${f.location.sheet}, row: ${f.location.row}, column: ${f.location.column} }`];
        if (f.include !== undefined)
            parts.push(`include: ${f.include}`);
        if (f.required !== undefined)
            parts.push(`required: ${f.required}`);
        return `{ ${parts.join(", ")} }`;
    });
    return `[\n    ${items.join(",\n    ")},\n  ]`;
}
function printStructure(fields, indent) {
    if (fields.length === 0)
        return "[]";
    const pad = "  ".repeat(indent + 1);
    const closePad = "  ".repeat(indent);
    const items = fields.map((f) => printStructureField(f, indent + 1));
    return `[\n${pad}${items.join(`,\n${pad}`)},\n${closePad}]`;
}
function printStructureField(f, indent) {
    switch (f.type) {
        case "text":
        case "number":
        case "decimal":
        case "boolean":
            return `fileReaderStructure.${f.type}(${quote(f.name)})`;
        case "date":
        case "datetime":
            return `fileReaderStructure.${f.type}(${quote(f.name)}, ${quote(f.format)})`;
        case "object":
            return `fileReaderStructure.object(${quote(f.name)}, ${printStructure(f.properties, indent)})`;
        case "array":
            return `fileReaderStructure.array(${quote(f.name)}, ${printStructureField(f.itemType, indent)})`;
    }
}
function quote(s) {
    return JSON.stringify(s);
}
